  public function executeIndex()
  {
    return $this->forward('tipo_documental', 'list');
  }
  
  public function handleErrorupdate(){
	$this->forward('tipo_documental', 'create');
  }

  public function executeList()
  {
    
    $c = new Criteria();
	$parametros_consulta = "";	
	
	$subserie_id = $this->getRequestParameter('subserie_id');
	if($subserie_id != ""){
		$c->add(TipoDocumentalPeer::SUBSERIE_ID, $subserie_id);
		$parametros_consulta .= "&subserie_id=".$subserie_id;
	}
	
	///////////////////  DESCRIPCION UBICACION ///////////////////////////
	$subserie = SubseriePeer::retrieveByPk($subserie_id);
	
	$this->name_subserie = ucwords(mb_strtolower($subserie->getDescripcion()));
	$this->id_serie = $subserie->getSerieId();
	$this->name_serie = ucwords(mb_strtolower($subserie->getSerie()->getDescripcion()));
	$this->name_dependencia = ucwords(mb_strtolower($subserie->getSerie()->getDependencia()->getNombre()));
		
	//////////////////////////////////////////////////////////////////////////////////
	$c->addAscendingOrderByColumn(TipoDocumentalPeer::ORDEN);
	//////////////////////////////////////////////////////////////////////////////////

	$pager=new sfPropelPager('TipoDocumental',25);
	$pager->setCriteria($c);
	$pager->setPage($this->getRequestParameter('page',1));
	$pager->init();
	$this->pager=$pager;
	$this->filtros_consulta = $parametros_consulta;
  }

  public function executeAsociarServicio()
  {
        $this->tipodocumental_id = !empty(trim($this->getRequestParameter('tipodocumental_id'))) ? $this->getRequestParameter('tipodocumental_id') : null;
        $this->subserie_id = !empty(trim($this->getRequestParameter('subserie_id'))) ? $this->getRequestParameter('subserie_id') : null;
        $this->servicio = new Servicio();
        $this->uniddoc_tiposerv = UnidadDocumentalTiposervicioPeer::getUnidocTipoServByTipoDocId($this->tipodocumental_id);
  }

  public function executeUpdateServicio()
  {
    try
    {
      $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
      $tiposervicio_id = $this->getRequestParameter('tiposervicio_id');
      $expediente_id = $this->getRequestParameter('expediente_id');
      $tipodocumental_id = $this->getRequestParameter('tipodocumental_id');
      $subserie_id = intval($this->getRequestParameter('subserie_id'));

      if(!is_numeric($expediente_id)) //validar que sea integer
      {
        $this->getUser()->setFlash('error_message', 'El expediente ID no es v&aacute;lido o no existe en el sistema.');
        return $this->redirect($this->getRequest()->getScriptName().'/tipo_documental/asociarServicio?tipodocumental_id='.$tipodocumental_id.'&subserie_id='.$subserie_id);
      }

      //validar que el expediente exista
      $unidad_documental = UnidadDocumentalPeer::retrieveByPK($expediente_id);
      if($unidad_documental == null)
      {
        $this->getUser()->setFlash('error_message', 'El expediente ID no es v&aacute;lido o no existe en el sistema.');
        return $this->redirect($this->getRequest()->getScriptName().'/tipo_documental/asociarServicio?tipodocumental_id='.$tipodocumental_id.'&subserie_id='.$subserie_id);
      }

      $found_subserie_id = $unidad_documental ? $unidad_documental->getSubserieId() : null;
      if($found_subserie_id !== null)
      {
          if($found_subserie_id === $subserie_id)
          {
              //validar que no exista ya el servicio para ese expediente
              $existing = UnidaddocumentalTiposervicioPeer::verifyAlreadyExist($expediente_id, $tiposervicio_id,$tipodocumental_id);
              if(count($existing) == 0)
              {
                UnidaddocumentalTiposervicioPeer::addNewUnidaddocumentalTiposervicio($expediente_id, $tiposervicio_id, $tipodocumental_id,$usuariologuiado);

                $this->getUser()->setFlash('success_message', 'El servicio ha sido generado exitosamente');
                return $this->redirect($this->getRequest()->getScriptName().'/tipo_documental/asociarServicio?tipodocumental_id='.$tipodocumental_id.'&subserie_id='.$subserie_id);   
              }
              else
              {
                $this->getUser()->setFlash('error_message', 'El servicio ya se encuentra asociado al expediente ID.');
                return $this->redirect($this->getRequest()->getScriptName().'/tipo_documental/asociarServicio?tipodocumental_id='.$tipodocumental_id.'&subserie_id='.$subserie_id);
              }         
          }
          else
          {
            $this->getUser()->setFlash('error_message', 'El expediente ID no pertenece a la subserie seleccionada.');
            return $this->redirect($this->getRequest()->getScriptName().'/tipo_documental/asociarServicio?tipodocumental_id='.$tipodocumental_id.'&subserie_id='.$subserie_id);
          }
      }
      else
      {
        $this->getUser()->setFlash('error_message', 'El expediente ID no es v&aacute;lido o no existe en el sistema.');
        return $this->redirect($this->getRequest()->getScriptName().'/tipo_documental/asociarServicio?tipodocumental_id='.$tipodocumental_id.'&subserie_id='.$subserie_id);
      }
    }
    catch (PropelException $th)
    {
			return $th->getMessage();
    } 
    catch (\Exception $th) 
    {
        return $th->getMessage();
    } 
    catch (\Throwable $th) 
    {
        return $th->getMessage();
    }
  }

  public function executeValidate()
  {
    $tipo_documental = TipoDocumentalPeer::retrieveByPk($this->getRequestParameter('tipodocumental_id'));
    $tipo_documental_anterior = $tipo_documental->copy();
    //********************************************************************************************************
    $tipo_documental->setEsObligatorio(empty($tipo_documental->getEsObligatorio()) ? 1 : 0);
    $tipo_documental->save();
    //********************************************************************************************************
    TipoDocumentalPeer::guardarAuditoria($tipo_documental_anterior,$tipo_documental);
    //********************************************************************************************************
    $this->tipo_documental = $tipo_documental;
    $this->forward404Unless($tipo_documental);
  }

  public function executeEnableTipoServicio()
  {
    $servicio_asociado = UnidaddocumentalTiposervicioPeer::retrieveByPk($this->getRequestParameter('unidaddocumentaltiposervicio_id'));
    $servicio_asociado_anterior = $servicio_asociado->copy();
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    //********************************************************************************************************
    $servicio_asociado->setEstaActivo(empty($servicio_asociado->getEstaActivo()) ? 1 : 0);
    $servicio_asociado->save();
    //********************************************************************************************************
    AuditLogPeer::guardarAuditoriaLite(UnidaddocumentalTiposervicioPeer::getOMClass(),$servicio_asociado_anterior,$servicio_asociado,ModulesEnable::Seguridad,
      $servicio_asociado->getPrimaryKey(),$usuariologuiado);
    //********************************************************************************************************
    $this->servicio_asociado = $servicio_asociado;
    $this->forward404Unless($servicio_asociado);
  }

  public function executeShow()
  {
    $this->tipo_documental = TipoDocumentalPeer::retrieveByPk($this->getRequestParameter('tipodocumental_id'));
    $this->name_subserie = ucwords(mb_strtolower($this->tipo_documental->getSubserie()->getDescripcion()));
	$this->name_serie = ucwords(mb_strtolower($this->tipo_documental->getSubserie()->getSerie()->getDescripcion()));
	$this->name_dependencia = ucwords(mb_strtolower($this->tipo_documental->getSubserie()->getSerie()->getDependencia()->getNombre()));
