    $this->tipo_documental = new TipoDocumental();
    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $this->tipo_documental = TipoDocumentalPeer::retrieveByPk($this->getRequestParameter('tipodocumental_id'));
    $this->forward404Unless($this->tipo_documental);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('tipodocumental_id'))
    {
      $tipo_documental = new TipoDocumental();
    }
    else
    {
      $tipo_documental = TipoDocumentalPeer::retrieveByPk($this->getRequestParameter('tipodocumental_id'));
      $tipo_documental_anterior = $tipo_documental->copy();
      $this->forward404Unless($tipo_documental);
    }
    //****************************************************************************************
    $tipo_documental->setSubserieId($this->getRequestParameter('subserie_id') ? $this->getRequestParameter('subserie_id') : null);
	$tipo_documental->setSoporteunidaddocumentalId($this->getRequestParameter('soporteunidaddocumental_id') ? $this->getRequestParameter('soporteunidaddocumental_id') : null);
    $tipo_documental->setCodigo($this->getRequestParameter('codigo'));
    $tipo_documental->setDescripcion($this->getRequestParameter('descripcion'));
    $tipo_documental->setOrden($this->getRequestParameter('orden'));
    if($this->getRequestParameter('cierra_expediente') !== null)
    {
       $tipo_documental->setCierraExpediente(1);
    }
    else
    {
      $tipo_documental->setCierraExpediente(0);
    }

    $tipo_documental->save();
    //*****************************************************************************************************
    TipoDocumentalPeer::guardarAuditoria($tipo_documental_anterior,$tipo_documental);
    //*****************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/tipo_documental/show?tipodocumental_id='.$tipo_documental->getTipodocumentalId().'&subserie_id='.$this->getRequestParameter('subserie_id'));
  }

  public function executeDelete()
  {
    $tipo_documental = TipoDocumentalPeer::retrieveByPk($this->getRequestParameter('tipodocumental_id'));
    $this->forward404Unless($tipo_documental);
    $tipo_documental->delete();
  }
